//! Phase 9 (optimization and candidate generation) compared with BoTorch on
//! the fixtures of `tests/fixtures/phase9_optim/` (generated by
//! `scripts/generate_fixtures.py --phase 9-optim` with BoTorch main). Every
//! comparison starts from BoTorch's inputs (initial conditions, recorded
//! random draws), so the results must agree to round-off:
//!
//! * `optimize_acqf_discrete`, `optimize_acqf_mixed` (best and all restarts,
//!   sequential `q = 2`), `optimize_acqf_discrete_local_search` (given
//!   starts; recorded lattice points for `q = 3`),
//!   `optimize_acqf_mixed_alternating` (recorded starting points),
//!   `optimize_acqf_cyclic` (a deterministic initial-condition generator);
//! * `gen_candidates_torch` (Adam; the number of steps must agree),
//!   `gen_candidates_scipy` in BoTorch's serial mode, post-processing;
//! * the stopping criterion's weights (bitwise for the defaults) and
//!   decisions, `prune_candidates`, `maximize_samples`, the constrained
//!   scores, the truncated normal perturbations;
//! * `fit_gpytorch_mll_torch` / `fit_gpytorch_mll_scipy` and
//!   `batch_cross_validation`.
//!
//! Run with `--nocapture` for the table of worst errors.

mod common;

use std::collections::BTreeMap;
use std::sync::Arc;

use botorch_core::acquisition::{
    AcquisitionFunction, LogExpectedImprovement, QLogExpectedImprovement,
    QLogExpectedImprovementOptions,
};
use botorch_core::fit::{fit_gpytorch_mll, FitOptions};
use botorch_core::generation::{
    constrained_scores, gen_candidates_torch, maximize_samples, TorchGenOptions,
};
use botorch_core::models::PosteriorMeanModel;
use botorch_core::models::{BatchedMultiOutputGP, BatchedMultiOutputGPOptions, Model};
use botorch_core::optim::adam::AdamOptions;
use botorch_core::optim::cyclic::optimize_acqf_cyclic;
use botorch_core::optim::discrete::LocalSearchOptions;
use botorch_core::optim::fit::{fit_gpytorch_mll_scipy, fit_gpytorch_mll_torch};
use botorch_core::optim::minimize::TorchMinimizeOptions;
use botorch_core::optim::mixed::{
    mixed_problem, optimize_acqf_mixed_alternating, MixedAlternatingOptions, MixedProblem,
};
use botorch_core::optim::stopping::{expma_weights, ExpMaStoppingCriterion, StoppingCriterion};
use botorch_core::optim::{
    gen_candidates_lbfgsb_joint, optimize_acqf_detailed, optimize_acqf_discrete,
    optimize_acqf_discrete_local_search, optimize_acqf_mixed, prune_candidates,
    truncated_normal_perturbations_from_uniform, IcGenerator, LinearConstraint,
    OptimizeAcqfOptions, ParameterConstraints, PostProcessing,
};
use botorch_core::sampling::SobolQMCNormalSampler;
use botorch_core::Matrix;
