use rand::rngs::Xoshiro256PlusPlus;
use rand::SeedableRng;
use serde::Deserialize;
use serde_json::Value;

/// Relative tolerance of values computed from identical inputs (the
/// optimizers reproduce BoTorch's iterates).
const TOL: f64 = 1e-9;
/// Relative tolerance of optimized candidates: at a converged optimum the
/// objective is flat, so round-off differences of ~1e-15 in the gradients
/// move the final iterate by up to ~sqrt(eps); measured worst 1.6e-9 (the
/// acquisition values agree to 5e-15).
const XTOL: f64 = 1e-8;

#[derive(Deserialize)]
struct ModelSpec {
    train_x: Vec<Vec<f64>>,
    train_y: Vec<Vec<f64>>,
    param_names: Vec<String>,
    raw_params: Vec<f64>,
}

fn load() -> Vec<Value> {
    let dir = fixture_dir().join("phase9_optim");
    let mut paths: Vec<_> = std::fs::read_dir(&dir)
        .expect("phase9_optim fixtures")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    assert!(!paths.is_empty());
    paths
        .iter()
        .map(|p| serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap())
        .collect()
}

fn f(v: &Value) -> f64 {
    match v {
        Value::String(s) => s.parse().unwrap_or(f64::NAN),
        _ => v.as_f64().unwrap(),
    }
}

fn flat(v: &Value) -> Vec<f64> {
    match v {
        Value::Array(a) => a.iter().flat_map(flat).collect(),
        _ => vec![f(v)],
    }
}

fn rows(v: &Value) -> Vec<Vec<f64>> {
    v.as_array().unwrap().iter().map(flat).collect()
}

/// `b x q x d` JSON arrays as candidate sets.
fn sets(v: &Value) -> Vec<Matrix> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|s| matrix(&rows(s)))
        .collect()
}

fn model_from(spec: &ModelSpec) -> BatchedMultiOutputGP {
    let mut m = BatchedMultiOutputGP::new(
        vec![matrix(&spec.train_x)],
        vec![matrix(&spec.train_y)],
        vec![],
        BatchedMultiOutputGPOptions::default(),
    )
    .unwrap();
    let names: Vec<String> = m.parameter_names().into_iter().map(|(n, _)| n).collect();
    assert_eq!(names, spec.param_names, "parameter names and order");
    m.set_raw_parameters(&spec.raw_params).unwrap();
    m
}

struct Setup {
    name: String,
    d: usize,
    logei: LogExpectedImprovement,
    qlogei: QLogExpectedImprovement,
    bounds: Matrix,
}

fn setup(fx: &Value) -> Setup {
    let spec: ModelSpec = serde_json::from_value(fx["model"].clone()).unwrap();
    let d = fx["d"].as_u64().unwrap() as usize;
    let model: Arc<dyn Model> = Arc::new(model_from(&spec));
    let best_f = f(&fx["best_f"]);
    let logei = LogExpectedImprovement::new(model.clone(), best_f, true).unwrap();
    let pm: Arc<dyn Model> = Arc::new(PosteriorMeanModel::new(model));
    let qlogei = QLogExpectedImprovement::new(
        pm,
        best_f,
        QLogExpectedImprovementOptions {
            sampler: Some(Arc::new(SobolQMCNormalSampler::new(1, Some(0)).unwrap())),
            ..Default::default()
        },
    )
    .unwrap();
    let bounds = Matrix::from_fn(2, d, |i, _| i as f64);
    Setup {
        name: fx["name"].as_str().unwrap().to_string(),
        d,
        logei,
        qlogei,
        bounds,
    }
}

fn first_row(m: &Matrix) -> Matrix {
    m.rows(0, 1).into_owned()
}

#[test]
fn parity_discrete_mixed_local_search_alternating() {
    let mut report = Report::default();
    for fx in load() {
        let s = setup(&fx);
        let name = s.name.as_str();
        // optimize_acqf_discrete.
        let dfx = &fx["discrete"];
        let choices = matrix(&rows(&dfx["choices"]));
        let r = optimize_acqf_discrete(&s.logei, 1, &choices, true, None, None).unwrap();
        report.check_slices(
            name,
            "discrete q=1 candidates",
            &matrix_rows(&r.candidates),
            &flat(&dfx["q1"]["candidates"]),
            TOL,
        );
        report.check_slices(
            name,
            "discrete q=1 value",
            &r.acq_values,
            &[f(&dfx["q1"]["value"])],
            TOL,
        );
        let avoid = matrix(&rows(&dfx["x_avoid"]));
        let c = &dfx["constraint"];
        let cons = vec![LinearConstraint::intra_point(
            c["indices"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_u64().unwrap() as usize)
                .collect(),
            flat(&c["coefficients"]),
            f(&c["rhs"]),
        )
        .unwrap()];
        let r = optimize_acqf_discrete(&s.qlogei, 3, &choices, true, Some(&avoid), Some(&cons))
            .unwrap();
        report.check_slices(
            name,
            "discrete q=3 candidates",
            &matrix_rows(&r.candidates),
            &flat(&dfx["q3"]["candidates"]),
            TOL,
        );
        report.check_slices(
            name,
            "discrete q=3 values",
            &r.acq_values,
            &flat(&dfx["q3"]["values"]),
            TOL,
        );
        let r = optimize_acqf_discrete(&s.qlogei, 3, &choices, false, None, None).unwrap();
        report.check_slices(
            name,
            "discrete q=3 not unique candidates",
            &matrix_rows(&r.candidates),
            &flat(&dfx["q3_not_unique"]["candidates"]),
            TOL,
        );
        report.check_slices(
            name,
            "discrete q=3 not unique values",
            &r.acq_values,
            &flat(&dfx["q3_not_unique"]["values"]),
            TOL,
        );

        // optimize_acqf_mixed from BoTorch's initial conditions.
        let mfx = &fx["mixed"];
        let ics = sets(&mfx["initial_conditions"]);
        let ffl: Vec<BTreeMap<usize, f64>> = mfx["fixed_features_list"]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| {
                m.as_object()
                    .unwrap()
                    .iter()
                    .map(|(k, v)| (k.parse().unwrap(), f(v)))
                    .collect()
            })
            .collect();
        let opts = OptimizeAcqfOptions {
            batch_initial_conditions: Some(ics.clone()),
            ..Default::default()
        };
        let r = optimize_acqf_mixed(&s.logei, &s.bounds, 1, 5, &ffl, 0, &opts, true).unwrap();
        report.check_slices(
            name,
            "mixed q=1 candidates",
            &matrix_rows(&r.candidates),
            &flat(&mfx["q1"]["candidates"]),
            XTOL,
        );
        report.check_slices(
            name,
            "mixed q=1 value",
            &[r.acq_value],
            &[f(&mfx["q1"]["value"])],
            TOL,
        );
        let r = optimize_acqf_mixed(&s.logei, &s.bounds, 1, 5, &ffl, 0, &opts, false).unwrap();
        let all: Vec<f64> = r
            .restarts
            .iter()
            .flat_map(|(c, _)| matrix_rows(c))
            .collect();
        let vals: Vec<f64> = r.restarts.iter().map(|(_, v)| *v).collect();
        report.check_slices(
            name,
            "mixed q=1 all candidates",
            &all,
            &flat(&mfx["q1_all"]["candidates"]),
            XTOL,
        );
        report.check_slices(
            name,
            "mixed q=1 all values",
            &vals,
            &flat(&mfx["q1_all"]["values"]),
            TOL,
        );
        let r = optimize_acqf_mixed(&s.qlogei, &s.bounds, 2, 5, &ffl, 0, &opts, true).unwrap();
        report.check_slices(
            name,
            "mixed q=2 candidates",
            &matrix_rows(&r.candidates),
            &flat(&mfx["q2"]["candidates"]),
            XTOL,
        );
        report.check_slices(
            name,
            "mixed q=2 value",
            &[r.acq_value],
            &[f(&mfx["q2"]["value"])],
            TOL,
        );

        // Local search.
        let lfx = &fx["local_search"];
        let levels = flat(&lfx["levels"]);
        let dc = vec![levels; s.d];
        let bic = matrix(&rows(&lfx["batch_initial_conditions"]));
        let opts = LocalSearchOptions {
            num_restarts: 4,
            ..Default::default()
        };
        let mut rng = Xoshiro256PlusPlus::seed_from_u64(0);
        let r = optimize_acqf_discrete_local_search(
            &s.logei,
            &dc,
            1,
            &opts,
            &[],
            None,
            Some(&bic),
            None,
            true,
            &mut rng,
        )
        .unwrap();
        report.check_slices(
            name,
            "local search q=1 candidates",
            &matrix_rows(&r.candidates),
            &flat(&lfx["q1"]["candidates"]),
            TOL,
        );
        report.check_slices(
            name,
            "local search q=1 value",
            &r.acq_values,
            &[f(&lfx["q1"]["value"])],
            TOL,
        );
        let recorded: Vec<Matrix> = lfx["lattice_points"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| matrix(&rows(p)))
            .collect();
        let step = std::sync::atomic::AtomicUsize::new(0);
        let lattice = |_avoid: &Matrix| -> botorch_core::Result<Matrix> {
            Ok(recorded[step.fetch_add(1, std::sync::atomic::Ordering::SeqCst)].clone())
        };
        let opts = LocalSearchOptions {
            num_restarts: 4,
            raw_samples: 48,
            ..Default::default()
        };
        let r = optimize_acqf_discrete_local_search(
            &s.qlogei,
            &dc,
            3,
            &opts,
            &[],
            None,
            None,
            Some(&lattice),
            true,
            &mut rng,
        )
        .unwrap();
        report.check_slices(
            name,
            "local search q=3 candidates",
            &matrix_rows(&r.candidates),
            &flat(&lfx["q3"]["candidates"]),
            TOL,
        );
        report.check_slices(
            name,
            "local search q=3 value",
            &r.acq_values,
            &[f(&lfx["q3"]["value"])],
            TOL,
        );

        // Mixed alternating from BoTorch's starting points.
        let afx = &fx["alternating"];
        let dims = |v: &Value| -> BTreeMap<usize, Vec<f64>> {
            v.as_object()
                .unwrap()
                .iter()
                .map(|(k, vals)| (k.parse().unwrap(), flat(vals)))
                .collect()
        };
        let start = matrix(&rows(&afx["starting_points"]));
        for (label, acqf, q) in [
            ("q1", &s.logei as &dyn AcquisitionFunction, 1usize),
            ("q2", &s.qlogei as &dyn AcquisitionFunction, 2),
        ] {
            let (problem, relaxed) = mixed_problem(
                acqf,
                &s.bounds,
                &dims(&afx["discrete_dims"]),
                &dims(&afx["cat_dims"]),
                &MixedAlternatingOptions::default(),
                6,
                32,
                &BTreeMap::new(),
                &ParameterConstraints::default(),
                true,
                None,
            )
            .unwrap();
            assert!(relaxed.is_empty());
            let starts = |p: &MixedProblem<'_>| -> botorch_core::Result<(Matrix, Vec<f64>)> {
                let sets: Vec<Matrix> = (0..start.nrows())
                    .map(|i| start.rows(i, 1).into_owned())
                    .collect();
                Ok((start.clone(), p.acq_function.forward_many(&sets)?))
            };
            let r =
                optimize_acqf_mixed_alternating(&problem, q, Some(0), Some(&starts), true).unwrap();
            report.check_slices(
                name,
                &format!("alternating {label} candidates"),
                &matrix_rows(&r.candidates),
                &flat(&afx[label]["candidates"]),
                XTOL,
            );
            report.check_slices(
                name,
                &format!("alternating {label} value"),
                &[r.acq_value],
                &[f(&afx[label]["value"])],
                TOL,
            );
        }
    }
    report.finish("phase 9: discrete, mixed, local search, alternating");
}

#[test]
fn parity_candidate_generation() {
    let mut report = Report::default();
    for fx in load() {
        let s = setup(&fx);
        let name = s.name.as_str();
        let g = &fx["generation"];
        let ics = sets(&g["initial_conditions"]);
        let no_fixed = BTreeMap::new();
        // gen_candidates_torch with BoTorch's defaults and custom settings.
        let r = gen_candidates_torch(
            &ics,
            &s.logei,
            &s.bounds,
            &no_fixed,
            &TorchGenOptions::default(),
            None,
        )
        .unwrap();
        let cands: Vec<f64> = r.candidates.iter().flat_map(matrix_rows).collect();
        report.check_slices(
            name,
            "gen_candidates_torch candidates",
            &cands,
            &flat(&g["torch"]["candidates"]),
            XTOL,
        );
        report.check_slices(
            name,
            "gen_candidates_torch values",
            &r.acq_values,
            &flat(&g["torch"]["values"]),
            TOL,
        );
        assert_eq!(
            r.steps as u64,
            g["torch"]["steps"].as_u64().unwrap(),
            "{name}: Adam steps"
        );
        let custom = TorchGenOptions {
            adam: AdamOptions {
                lr: 0.05,
                betas: (0.8, 0.99),
                ..Default::default()
            },
            maxiter: 60,
            rel_tol: 1e-6,
            n_window: 5,
            ..Default::default()
        };
        let r = gen_candidates_torch(&ics, &s.logei, &s.bounds, &no_fixed, &custom, None).unwrap();
        let cands: Vec<f64> = r.candidates.iter().flat_map(matrix_rows).collect();
        report.check_slices(
            name,
            "gen_candidates_torch custom candidates",
            &cands,
            &flat(&g["torch_custom"]["candidates"]),
            XTOL,
        );
        report.check_slices(
            name,
            "gen_candidates_torch custom values",
            &r.acq_values,
            &flat(&g["torch_custom"]["values"]),
            TOL,
        );
        assert_eq!(
            r.steps as u64,
            g["torch_custom"]["steps"].as_u64().unwrap(),
            "{name}: Adam steps (custom)"
        );
        // gen_candidates_scipy in the serial mode (one problem, scipy's maxfun).
        let lb = botorch_core::lbfgsb::LbfgsbOptions {
            maxiter: 2000,
            maxfun: g["scipy_joint"]["maxfun"].as_u64().unwrap() as usize,
            ..Default::default()
        };
        let r = gen_candidates_lbfgsb_joint(
            &ics,
            &s.logei,
            &s.bounds,
            &no_fixed,
            &lb,
            usize::MAX,
            None,
        )
        .unwrap();
        let cands: Vec<f64> = r.iter().flat_map(|x| matrix_rows(&x.candidates)).collect();
        let vals: Vec<f64> = r.iter().map(|x| x.acq_value).collect();
        report.check_slices(
            name,
            "gen_candidates_scipy joint candidates",
            &cands,
            &flat(&g["scipy_joint"]["candidates"]),
            XTOL,
        );
        report.check_slices(
            name,
            "gen_candidates_scipy joint values",
            &vals,
            &flat(&g["scipy_joint"]["values"]),
            TOL,
        );
        // Post-processing.
        let step = f(&g["post_processing"]["step"]);
        let opts = OptimizeAcqfOptions {
            batch_initial_conditions: Some(ics.clone()),
            post_processing: Some(PostProcessing::new(move |sets: &[Matrix]| {
                Ok(sets
                    .iter()
                    .map(|x| x.map(|v| (v / step).round_ties_even() * step))
                    .collect())
            })),
            ..Default::default()
        };
        let r = optimize_acqf_detailed(&s.logei, &s.bounds, 1, 4, 0, &opts).unwrap();
        report.check_slices(
            name,
            "post-processing candidates",
            &matrix_rows(&r.candidates),
            &flat(&g["post_processing"]["candidates"]),
            TOL,
        );
        report.check_slices(
            name,
            "post-processing value",
            &[r.acq_value],
            &[f(&g["post_processing"]["value"])],
            TOL,
        );
        // Cyclic optimization with a deterministic initial-condition generator.
        let cyc = &g["cyclic"];
        let cyc_ics = sets(&cyc["initial_conditions"]);
        let gen_ics = cyc_ics.clone();
        let opts = OptimizeAcqfOptions {
            ic_generator: Some(IcGenerator::new(move |req| {
                Ok(gen_ics[..req.num_restarts].to_vec())
            })),
            ..Default::default()
        };
        let stopping = ExpMaStoppingCriterion::new(
            cyc["maxiter"].as_u64().unwrap() as usize,
            true,
            10,
            1.0,
            1e-5,
        );
        let r = optimize_acqf_cyclic(&s.qlogei, &s.bounds, 3, 4, 16, &opts, &stopping).unwrap();
        report.check_slices(
            name,
            "cyclic candidates",
            &matrix_rows(&r.candidates),
            &flat(&cyc["candidates"]),
            XTOL,
        );
        report.check_slices(
            name,
            "cyclic values",
            &r.acq_values,
            &flat(&cyc["values"]),
            TOL,
        );
        let _ = first_row(&s.bounds);
    }
    report.finish("phase 9: candidate generation");
}

#[test]
fn parity_utilities() {
    let mut report = Report::default();
    for fx in load() {
        let name = fx["name"].as_str().unwrap().to_string();
        let u = &fx["utilities"];
        // Stopping criterion: weights (bitwise for the defaults), decisions.
        for w in u["stopping"]["weights"].as_array().unwrap() {
            let eta = f(&w["eta"]);
            let n = w["n_window"].as_u64().unwrap() as usize;
            let ours = expma_weights(eta, n);
            let err = rel_err(&ours, &flat(&w["weights"]));
            if eta == 1.0 && n == 10 {
                assert_eq!(err, 0.0, "default weights must be torch's");
            }
            // float32 weights: torch's vectorized exp and sum are not
            // correctly rounded (at most a few float32 ulps).
            report.check(
                &name,
                &format!("stopping weights eta={eta} n={n}"),
                err,
                3e-7,
            );
        }
        let seq = flat(&u["stopping"]["sequence"]);
        for dcase in u["stopping"]["decisions"].as_array().unwrap() {
            let kw = &dcase["kwargs"];
            let mut c = ExpMaStoppingCriterion::new(
                kw.get("maxiter")
                    .map_or(10000, |v| v.as_u64().unwrap() as usize),
                kw.get("minimize").is_none_or(|v| v.as_bool().unwrap()),
                kw.get("n_window")
                    .map_or(10, |v| v.as_u64().unwrap() as usize),
                1.0,
                kw.get("rel_tol").map_or(1e-5, f),
            );
            let ours: Vec<bool> = seq.iter().map(|&v| c.evaluate(&[v])).collect();
            let theirs: Vec<bool> = dcase["stops"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_bool().unwrap())
                .collect();
            assert_eq!(ours, theirs, "{name}: stopping decisions {kw}");
        }
        // prune_candidates.
        let p = &u["prune"];
        let pruned = prune_candidates(
            &matrix(&rows(&p["candidates"])),
            &flat(&p["values"]),
            f(&p["tolerance"]),
        )
        .unwrap();
        report.check_slices(
            &name,
            "prune_candidates",
            &matrix_rows(&pruned),
            &flat(&p["pruned"]),
            0.0,
        );
        // maximize_samples (4 samples x 2 batches x 9 points).
        let m = &u["maximize_samples"];
        let obj = flat(&m["obj"]);
        let xs = flat(&m["X"]);
        for repl in [true, false] {
            let idx = maximize_samples(&obj, 4, 2, 9, repl).unwrap();
            let mut got = Vec::new();
            for b in 0..2 {
                for k in 0..4 {
                    let i = idx[b * 4 + k];
                    got.extend_from_slice(&xs[(b * 9 + i) * 2..(b * 9 + i + 1) * 2]);
                }
            }
            report.check_slices(
                &name,
                &format!("maximize_samples replacement={repl}"),
                &got,
                &flat(&m["selected"][if repl { "True" } else { "False" }]),
                0.0,
            );
        }
        let cs = &u["constrained_scores"];
        let scores = constrained_scores(&flat(&cs["y"]), &flat(&cs["c"]), 4, 9, 2).unwrap();
        report.check_slices(
            &name,
            "constrained scores",
            &scores,
            &flat(&cs["scores"]),
            0.0,
        );
        // Truncated normal perturbations from BoTorch's uniform draws.
        let t = &u["truncated_normal"];
        let center = flat(&t["center"]);
        let u_draws = matrix(&rows(&t["u"]));
        let centers = Matrix::from_fn(u_draws.nrows(), center.len(), |_, j| center[j]);
        let pert = truncated_normal_perturbations_from_uniform(
            &centers,
            &u_draws,
            f(&t["sigma"]),
            &matrix(&rows(&t["bounds"])),
        )
        .unwrap();
        report.check_slices(
            &name,
            "truncated normal perturbations",
            &matrix_rows(&pert),
            &flat(&t["perturbed"]),
            1e-12,
        );
    }
    report.finish("phase 9: utilities");
}

#[test]
fn parity_fits_and_cross_validation() {
    let mut report = Report::default();
    for fx in load() {
        let name = fx["name"].as_str().unwrap().to_string();
        let fits = &fx["fits"];
        for (label, opts) in [
            (
                "torch_200",
                TorchMinimizeOptions {
                    step_limit: Some(200),
                    ..Default::default()
                },
            ),
            (
                "torch_default",
                TorchMinimizeOptions {
                    step_limit: Some(3000),
                    ..Default::default()
                },
            ),
            (
                "torch_lr",
                TorchMinimizeOptions {
                    step_limit: Some(150),
                    adam: AdamOptions {
                        lr: 0.02,
                        ..Default::default()
                    },
                    ..Default::default()
                },
            ),
        ] {
            let e = &fits[label];
            let spec: ModelSpec = serde_json::from_value(e["model"].clone()).unwrap();
            let mut m = model_from(&spec);
            let r = fit_gpytorch_mll_torch(&mut m, None, None, &opts, None).unwrap();
            assert_eq!(r.status.name(), e["status"].as_str().unwrap());
            if let Some(twins) = e.get("twins").and_then(|t| t.as_array()) {
                // Run until the stopping criterion holds: Adam amplifies
                // round-off over hundreds of steps, so BoTorch's own outcome
                // varies between twins whose training inputs differ at
                // 1e-14 .. 1e-11. botorch_rs's must lie among them.
                let mut steps: Vec<u64> =
                    twins.iter().map(|t| t["step"].as_u64().unwrap()).collect();
                steps.push(e["step"].as_u64().unwrap());
                let (lo, hi) = (*steps.iter().min().unwrap(), *steps.iter().max().unwrap());
                assert!(
                    (lo..=hi).contains(&(r.step as u64)),
                    "{name} {label}: {} steps outside BoTorch's twins' {lo}..={hi}",
                    r.step
                );
                let mut fvals: Vec<f64> = twins.iter().map(|t| f(&t["fval"])).collect();
                fvals.push(f(&e["fval"]));
                let (flo, fhi) = fvals
                    .iter()
                    .fold((f64::INFINITY, f64::NEG_INFINITY), |(a, b), &v| {
                        (a.min(v), b.max(v))
                    });
                let excess = ((flo - r.fval).max(r.fval - fhi)).max(0.0) / fhi.abs().max(1.0);
                report.check(
                    &name,
                    &format!("fit {label} loss outside twins"),
                    excess,
                    TOL,
                );
                println!(
                    "{name} {label}: {} steps (BoTorch {} , twins {lo}..={hi}), loss {} (twins {flo} .. {fhi})",
                    r.step,
                    e["step"],
                    r.fval
                );
                continue;
            }
            assert_eq!(
                r.step as u64,
                e["step"].as_u64().unwrap(),
                "{name} {label}: steps"
            );
            report.check_slices(
                &name,
                &format!("fit {label} raw parameters"),
                m.raw_parameters().as_slice(),
                &flat(&e["raw_params"]),
                TOL,
            );
            report.check_slices(
                &name,
                &format!("fit {label} loss"),
                &[r.fval],
                &[f(&e["fval"])],
                TOL,
            );
        }
        let e = &fits["scipy"];
        let spec: ModelSpec = serde_json::from_value(e["model"].clone()).unwrap();
        let mut m = model_from(&spec);
        let r = fit_gpytorch_mll_scipy(
            &mut m,
            None,
            None,
            &botorch_core::lbfgsb::LbfgsbOptions::default(),
            None,
        )
        .unwrap();
        assert_eq!(
            r.step as u64,
            e["step"].as_u64().unwrap(),
            "{name} scipy: iterations"
        );
        report.check_slices(
            &name,
            "fit scipy raw parameters",
            m.raw_parameters().as_slice(),
            &flat(&e["raw_params"]),
            TOL,
        );
        report.check_slices(&name, "fit scipy loss", &[r.fval], &[f(&e["fval"])], TOL);

        // batch_cross_validation: one fold per batch element.
        let cv = &fx["cross_validation"];
        let x = rows(&cv["train_x"]);
        let y = rows(&cv["train_y"]);
        let n = x.len();
        let mut xs = Vec::new();
        let mut ys = Vec::new();
        for i in 0..n {
            let keep: Vec<usize> = (0..n).filter(|&j| j != i).collect();
            xs.push(matrix(
                &keep.iter().map(|&j| x[j].clone()).collect::<Vec<_>>(),
            ));
            ys.push(matrix(
                &keep.iter().map(|&j| y[j].clone()).collect::<Vec<_>>(),
            ));
        }
        let folds_x: Vec<f64> = xs.iter().flat_map(matrix_rows).collect();
        report.check_slices(
            &name,
            "cv folds train_X",
            &folds_x,
            &flat(&cv["folds_train_x"]),
            0.0,
        );
        let mut model =
            BatchedMultiOutputGP::new(xs, ys, vec![n], BatchedMultiOutputGPOptions::default())
                .unwrap();
        fit_gpytorch_mll(&mut model, FitOptions::default()).unwrap();
        report.check_slices(
            &name,
            "cv fitted raw parameters",
            model.raw_parameters().as_slice(),
            &flat(&cv["raw_params"]),
            TOL,
        );
        let mut mean = Vec::new();
        let mut var = Vec::new();
        for (i, xi) in x.iter().enumerate().take(n) {
            let p = model
                .posterior_at(i, &matrix(std::slice::from_ref(xi)), false)
                .unwrap();
            mean.push(p.mean[0]);
            var.push(p.covariance[(0, 0)]);
        }
        report.check_slices(&name, "cv posterior mean", &mean, &flat(&cv["mean"]), TOL);
        report.check_slices(
            &name,
            "cv posterior variance",
            &var,
            &flat(&cv["variance"]),
            TOL,
        );
    }
    report.finish("phase 9: fits and cross-validation");
}
